// Configuration for the Telegram bot.
//
// Note: Telegram Serverless (tgcloud) runs only .js modules with the `sdk`
// imports — there is no env-var mechanism at runtime, so configuration is
// resolved from:
//   1. `runtime-config.js` — auto-generated by the control plane (collector).
//      This is the live settings source for providers / models / admins /
//      defaults (written when the admin panel changes something, then pushed).
//   2. Static defaults below (used when the control plane hasn't written a
//      runtime config yet, or for values it doesn't manage).
//
// Engine modes:
//   mode: 'api'    — OpenAI-compatible providers (official Inception API,
//                     OpenAI, Anthropic gateways, local vLLM/ollama …).
//                     The chosen provider/model is defined in runtime config.
//   mode: 'direct' — free web chat (chat.inceptionlabs.ai) via sessions
//                     captured by the session collector (kept fresh).
//   mode: 'bridge' — your own inception-free-bridge instance behind the chat.

import { runtimeConfig } from './runtime-config.js';
import { hostSecret } from './host-secret.js';
import { sessions } from './sessions.js';

const defaults = {
  // ---- engine mode ----
  mode: 'direct',       // 'api' | 'direct' | 'bridge' (overridden by runtime)

  // ---- api mode (from control plane) ----
  providers: [],        // from runtimeConfig
  models: [],           // from runtimeConfig
  activeModelId: '',    // from runtimeConfig

  // ---- direct (web chat) mode ----
  sessions,            // captured sessions (auto-generated file)
  sessionTtlHours: 6,
  collectorUrl: '',     // session self-heal endpoint (set by collector)

  // ---- bridge mode ----
  bridgeBaseUrl: 'https://YOUR-BRIDGE-HOST',
  bridgeApiKey: 'YOUR-BRIDGE-API-KEY',

  // ---- shared ----
  model: 'mercury-3',   // fallback display when no active model
  timeoutMs: 60000,
  showThinking: true,
  thinkingPreviewChars: 400,
  maxHistoryTurns: 12,
  systemPrompt: 'You are a helpful assistant in a Telegram chat. Answer concisely.',
  allowGroups: true,

  // ---- control-plane reporting (bot -> collector) ----
  reportUrl: '',        // from runtimeConfig
  reportSecret: '',     // from runtimeConfig
};

function mergeRuntime(base) {
  const rt = runtimeConfig || {};
  const settings = rt.settings || {};
  const merged = { ...base };

  if (rt.mode) merged.mode = rt.mode;
  if (Array.isArray(rt.providers)) merged.providers = rt.providers;
  if (Array.isArray(rt.models)) merged.models = rt.models;
  if (rt.activeModelId) merged.activeModelId = rt.activeModelId;
  if (settings.defaultModelId) merged.activeModelId = merged.activeModelId || settings.defaultModelId;
  if (settings.showThinking != null) merged.showThinking = !!settings.showThinking;
  if (settings.thinkingPreviewChars != null) merged.thinkingPreviewChars = settings.thinkingPreviewChars;
  if (settings.maxHistoryTurns != null) merged.maxHistoryTurns = settings.maxHistoryTurns;
  if (settings.allowGroups != null) merged.allowGroups = !!settings.allowGroups;
  if (settings.defaultSystemPrompt) merged.systemPrompt = settings.defaultSystemPrompt;
  // host credentials come from host-secret.js, never from the public repo
  if (hostSecret.reportUrl) merged.reportUrl = hostSecret.reportUrl;
  if (hostSecret.reportSecret) merged.reportSecret = hostSecret.reportSecret;
  if (rt.reportUrl) merged.reportUrl = rt.reportUrl;
  if (rt.reportSecret) merged.reportSecret = rt.reportSecret;

  return merged;
}

export const config = mergeRuntime(defaults);
